/* Truck Simulator 3.9 — reusable procedural facade atlas, metre units. No external assets. */
(function(root){'use strict';
const sources={"brick":"data:image/webp;base64,","restaurant":"data:image/webp;base64,","glass":"data:image/webp;base64,","office":"data:image/webp;base64,","fubon":"data:image/webp;base64,","fubonCorner":"data:image/webp;base64,","warehouse":"data:image/webp;base64,","family":"data:image/webp;base64,","familySide":"data:image/webp;base64,","shops":"data:image/webp;base64,","betel":"data:image/webp;base64,","hardware":"data:image/webp;base64,","fence":"data:image/webp;base64,"};
const imgs={};for(const [k,src] of Object.entries(sources)){const im=new Image();im.src=src;imgs[k]=im;}
const colors={brick:'#a47660',restaurant:'#a47660',glass:'#6b9299',office:'#8c9692',fubon:'#737969',fubonCorner:'#737969',warehouse:'#acb4b5',family:'#c4ccc6',familySide:'#c4ccc6',shops:'#a59c89',betel:'#a59c89',hardware:'#a59c89',fence:'#7c9989'};
function create({box,flat,face,textureFace}){
 const v=(x,y,z,u,t)=>({x,y,z,u,t});
 // UV-mapped vertical planes are split in world metres for stable depth ordering and perspective.
 function panel(x1,z1,x2,z2,y,h,key){const im=imgs[key],color=colors[key]||'#9b9c96';let n=Math.max(1,Math.ceil(Math.hypot(x2-x1,z2-z1)/2.4)),m=Math.max(1,Math.ceil(h/3));for(let i=0;i<n;i++)for(let j=0;j<m;j++){let a=i/n,b=(i+1)/n,t=j/m,q=(j+1)/m;let V=(u,w)=>v(x1+(x2-x1)*u,y+h*(1-w),z1+(z2-z1)*u,u,w);textureFace([V(a,t),V(b,t),V(b,q),V(a,q)],im,color,key);}}
 function wall(x1,z1,x2,z2,y,h,key,repeat=1){for(let i=0;i<repeat;i++){let a=i/repeat,b=(i+1)/repeat;panel(x1+(x2-x1)*a,z1+(z2-z1)*a,x1+(x2-x1)*b,z1+(z2-z1)*b,y,h,key)}}
 // Edges: south (-z), east (+x), north (+z), west (-x). Facades are real world-space faces, not billboards.
 function building(x1,x2,z1,z2,h,keys,y=0){const k=typeof keys==='string'?{south:keys,east:keys,north:keys,west:keys}:keys;
 const edges=[[x1,z1,x2,z1,'south'],[x2,z1,x2,z2,'east'],[x2,z2,x1,z2,'north'],[x1,z2,x1,z1,'west']];for(const [a,b,c,d,side] of edges){let val=k[side]||'office';let [key,rep]=Array.isArray(val)?val:[val,1];wall(a,b,c,d,y,h,key,rep)}flat((x1+x2)/2,(z1+z2)/2,x2-x1,z2-z1,'#8c9491',0,y+h);}
 function tree(x,z,s=1){box(x,z,.23*s,.23*s,3.9*s,0,'#766957');const rgb=['#587b46','#668a4f','#74955b','#4a6e41','#8aa66a'];
 // Multi-lobed low-poly crown. Irregular ring heights avoid repeating square/diamond tree silhouettes.
 for(let q=0;q<3;q++){const cx=x+(q===1?.76:q===2?-.62:0)*s,cz=z+(q===1?-.35:q===2?.55:0)*s,cy=(3.95+(q===0?.45:0))*s,r=(q===0?1.18:1.03)*s,ring=[];for(let j=0;j<8;j++){const a=j*Math.PI/4,rr=r*(.90+((j*7+q*3)%5)*.045);ring.push(v(cx+Math.cos(a)*rr,cy+Math.sin(j*2+q)*.13*s,cz+Math.sin(a)*rr));}const top=v(cx+.12*s,cy+.94*s,cz),low=v(cx,cy-.7*s,cz);for(let j=0;j<8;j++){face([ring[j],ring[(j+1)%8],top],rgb[(j+q)%5]);face([ring[(j+1)%8],ring[j],low],rgb[(j+q+3)%4]);}}}
 function scooter(x,z,a=0,c='#4d6a73'){const p=(f,r,y)=>v(x+Math.sin(a)*f+Math.cos(a)*r,y,z+Math.cos(a)*f-Math.sin(a)*r);let wheelR=.23;for(const f of [-.54,.58]){for(let j=0;j<10;j++){let a0=j*Math.PI/5,a1=(j+1)*Math.PI/5;const q=(t,r)=>p(f+Math.cos(t)*wheelR,r,.24+Math.sin(t)*wheelR);face([q(a0,-.09),q(a1,-.09),q(a1,.09),q(a0,.09)],'#282b2b');for(const r of [-.095,.095])face([q(a0,r),q(a1,r),p(f,r,.24)],'#363b3c');}}
 const sideBody=[[-.72,.39],[-.66,.64],[-.12,.68],[.13,.31],[.39,.36],[.49,.72],[.65,.65],[.72,.38],[.40,.25],[-.38,.27]];for(const r of [-.22,.22])face(sideBody.map(([f,y])=>p(f,r,y)),c);for(let j=0;j<sideBody.length;j++){const [f,y]=sideBody[j],[g,h]=sideBody[(j+1)%sideBody.length];face([p(f,-.22,y),p(g,-.22,h),p(g,.22,h),p(f,.22,y)],c);}
 let u=p(-.32,0,0);box(u.x,u.z,.44,.66,.12,.65,'#282b2c',a);u=p(.53,0,0);box(u.x,u.z,.12,.13,.48,.55,'#3f4647',a);box(u.x,u.z,.65,.13,.10,1.05,'#20292c',a);let head=p(.57,0,0);box(head.x,head.z,.32,.18,.15,.87,'#c8c9bc',a);for(let side of [-1,1]){let m=p(.51,side*.30,0);box(m.x,m.z,.12,.10,.04,1.18,'#919b99',a);}}
 function signal(x,z,a=0,l=5){box(x,z,.22,.22,5.7,.06,'#697979');let xx=x+Math.cos(a)*l/2,zz=z-Math.sin(a)*l/2;box(xx,zz,l,.22,.18,5.55,'#778484',a);let dx=x+Math.cos(a)*(l-.9),dz=z-Math.sin(a)*(l-.9);box(dx,dz,1.7,.32,.52,5.06,'#303d3f',a);for(let j=-1;j<=1;j++){let xx=dx+Math.cos(a)*j*.5,zz=dz-Math.sin(a)*j*.5;box(xx,zz,.30,.34,.30,5.17,j===1?'#43cf88':'#58625a',a);} }
 function curb(x,z,w,l,a=0){box(x,z,w,l,.14,0,'#b7b6a7',a);}
 function lamp(x,z,a=0){box(x,z,.13,.13,5.0,.1,'#718180');box(x+Math.cos(a)*.48,z-Math.sin(a)*.48,1.05,.20,.15,5.02,'#aab1a9',a);}
 function roadArrow(x,z,a=0){const p=(f,r)=>v(x+Math.sin(a)*f+Math.cos(a)*r,.048,z+Math.cos(a)*f-Math.sin(a)*r);face([p(-1.6,-.15),p(.4,-.15),p(.4,-.55),p(1.55,0),p(.4,.55),p(.4,.15),p(-1.6,.15)],'#e9e6d9');}
 function mountain(x,z,w,h){let p=[v(x-w/2,0,z),v(x-w*.35,h*.42,z),v(x-w*.16,h*.8,z),v(x+w*.03,h*.57,z),v(x+w*.17,h,z),v(x+w*.32,h*.55,z),v(x+w/2,0,z)];face(p,'#869c9e');}
 return {panel,wall,building,tree,scooter,signal,curb,lamp,roadArrow,mountain};
}
root.StreetAssets={create,ready:()=>Object.values(imgs).every(i=>i.complete&&i.naturalWidth>0)};
})(globalThis);
